insert into bi_template (id, tenant_id, code, version, name, category, section_f_element_code, description, status, industry_code, template_kind, kernel_version) values
  ('ef37f742-6dbd-5a1a-920b-1fbea8f9871f', null, 'REG-F-01', 1, 'Scaffold register and inspection records', 'scaffolds', 'HSF-F-01', 'Scaffold collapses and falls from scaffolds cause serious injuries and deaths. The register proves each scaffold was inspected by your appointed scaffold inspector, and inspected again after bad weather or any change. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('1a88bcc5-71ff-5df5-b677-7349ba8aa449', null, 'REG-F-02', 1, 'Ladder register and inspections', 'ladders', 'HSF-F-02', 'Falls from ladders are one of the most common serious injuries in small businesses. The register shows every ladder is inspected and that damaged ones are taken out of service instead of being left for someone to use. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('d3d23e55-cb3b-5b66-b119-fd580aa12517', null, 'REG-F-03', 1, 'Lifting machines and lifting tackle register with load tests and inspections', 'lifting', 'HSF-F-03', 'A failed chain, sling or hoist can drop a load onto people. The register and certificates prove each item was load tested and inspected, and inspectors and clients ask for the certificates before a crane or hoist is used on site. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('d9f3241d-af31-54c4-ad27-900a2d27eaab', null, 'REG-F-04', 1, 'Portable electrical tools and equipment register with inspections', 'electrical', 'HSF-F-04', 'Damaged cables and faulty tools cause shocks, burns and fires. The register proves every drill, grinder and extension lead is inspected and that faulty items are tagged out before someone is hurt. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('cd03242f-8a9f-5b06-819e-c17797c7712d', null, 'REG-F-05', 1, 'Electrical installation certificate of compliance and installation inspection register', 'electrical', 'HSF-F-05', 'An unsafe electrical installation can cause electrocution and fire. The certificate proves a registered person tested the installation and the register shows it is inspected; landlords, insurers and inspectors routinely ask for both. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('8399f2a7-b50d-5886-a590-c295797251c4', null, 'REG-F-06', 1, 'Fire equipment register with service dates', 'fire', 'HSF-F-06', 'Fire equipment that is empty, blocked or out of service cannot save anyone. The register shows every item is checked and serviced, and your insurer and the local fire authority may ask to see it. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('c1e4afd3-076c-54a6-86ef-d25e484ed949', null, 'REG-F-07', 1, 'Emergency lighting and signage inspections', 'general', 'HSF-F-07', 'When the power fails during an emergency, people need lights and signs to find the way out. These records prove emergency lighting and signage are tested and repaired when they fail. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('05b0e80c-4bd3-5679-8bd8-05f6086964d8', null, 'REG-F-08', 1, 'Pressure equipment register with inspections and certificates', 'general', 'HSF-F-08', 'Pressure vessels can explode with enough force to kill. The register and certificates prove every vessel was inspected and tested and that its safety devices work. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('ce9a27bc-827a-59f1-9c90-88bc25188288', null, 'REG-F-09', 1, 'Vehicle and mobile plant register with daily checks and maintenance', 'general', 'HSF-F-09', 'Mobile plant and vehicles injure pedestrians and operators when brakes, lights, horns or reverse alarms fail. Daily checks catch faults before a shift starts, and the maintenance record shows faults are fixed, not just noted.', 'draft', null, 'register', '1.1.0'),
  ('b97d1f85-3c26-59f5-ae0c-2c5a3fd86de9', null, 'REG-F-10', 1, 'Excavation inspection register', 'general', 'HSF-F-10', 'Trench collapses bury workers in seconds. Checking every excavation every day, and again after rain or other changes, is how you catch cracking, water and loose material before anyone is trapped.', 'draft', null, 'register', '1.1.0'),
  ('725922fc-9966-5c3c-bf2e-e26e6dbc48ab', null, 'REG-F-11', 1, 'Personal protective equipment issue register and inspection', 'ppe', 'HSF-F-11', 'Personal protective equipment is the last line of defence, so it must match the hazard, fit the person and be in good condition. The signed register proves each person received the right equipment, and it helps when a worker disputes what they were given.', 'draft', null, 'register', '1.1.0'),
  ('9ea00afe-ce55-5bd8-b318-241c0b0f70f7', null, 'REG-F-12', 1, 'Hazardous chemical agent register with safety data sheets, quantities and storage', 'chemicals', 'HSF-F-12', 'You cannot control chemicals you have not listed. The register and safety data sheets tell workers, first aiders and emergency services what each substance does and how to handle a spill or exposure, and they underpin the chemical risk assessment and any medical surveillance under the Hazardous Chemical Agents Regulations. Update it whenever a chemical is added, removed or moved.', 'draft', null, 'register', '1.1.0'),
  ('b58cdca7-b106-55b4-b9ca-d360d706f080', null, 'REG-F-13', 1, 'Asbestos inventory and register', 'general', 'HSF-F-13', 'Asbestos fibres released from damaged material cause fatal lung diseases years after exposure. The inventory tells maintenance staff and contractors where asbestos is so nobody drills, cuts or breaks it unprotected, and the inspections track its condition. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('e9fff379-b2ea-5c16-a006-4b36fb30c5a1', null, 'REG-F-14', 1, 'Machine guarding inspection register', 'general', 'HSF-F-14', 'Unguarded belts, gears, blades and rollers cause amputations. The register proves guards are checked and that a machine is stopped when a guard is missing. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('c1d5d73c-b957-530b-9b2e-365ebb96ff5d', null, 'REG-F-15', 1, 'Housekeeping and walkabout inspection records', 'general', 'HSF-F-15', 'Most slips, trips and many fires start with poor housekeeping. A supervisor walking the site every month and writing down what needs fixing shows you look for hazards before they cause harm.', 'draft', null, 'register', '1.1.0'),
  ('ebdb4098-8a82-5150-91cc-a56c3a634864', null, 'REG-F-16', 1, 'Stacking and storage inspections', 'general', 'HSF-F-16', 'Collapsing racks and falling stock crush people. The monthly inspection by your stacking and storage supervisor shows stacks are stable, racking is undamaged and loads stay within the marked limits.', 'draft', null, 'register', '1.1.0'),
  ('0cc84cdf-bee6-5318-bd1a-25ada8356f55', null, 'REG-F-17', 1, 'Fall arrest equipment register and inspections', 'general', 'HSF-F-17', 'A harness that fails in a fall is worse than none. Checking fall arrest equipment before each use, and taking it out of service after a fall or damage, is what keeps it reliable.', 'draft', null, 'register', '1.1.0'),
  ('2dee8c2e-79e5-5f98-a96f-68f8eed42db8', null, 'REG-F-18', 1, 'Confined space register', 'general', 'HSF-F-18', 'People die in confined spaces from lack of oxygen, toxic gas or engulfment, and often the rescuers die too. The register makes sure every such space is known, marked and entered only under a permit.', 'draft', null, 'register', '1.1.0'),
  ('8f33e7ee-37e3-5850-9a3b-d51d7b56342d', null, 'REG-F-19', 1, 'Explosive powered tool register', 'general', 'HSF-F-19', 'Explosive powered tools can fire nails through materials and people, and cartridges must never go missing. The issue log shows each tool and every cartridge went to an authorised operator and came back.', 'draft', null, 'register', '1.1.0'),
  ('68e43995-91c6-57fb-8851-7dfb06c1eed7', null, 'REG-F-20', 1, 'Welfare facilities inspection', 'general', 'HSF-F-20', 'Dirty or broken toilets, no clean water and nowhere hygienic to eat affect health and morale, and they are among the first things an inspector or worker complains about. The monthly check shows these facilities are kept working and clean.', 'draft', null, 'register', '1.1.0'),
  ('b2ffa8dc-4cab-54c5-8b1d-75b70d26f0b5', null, 'REG-F-21', 1, 'Lighting, ventilation and thermal environment measurements', 'general', 'HSF-F-21', 'Poor lighting causes accidents and eye strain, and poor ventilation or heat makes people ill. Measured results show where conditions need improving and prove you acted. Hold it at the interval your risk assessment or the practitioner sets; the File library shows a legal interval only once Care Net has verified one.', 'draft', null, 'register', '1.1.0'),
  ('796c92f6-9428-5f65-87fe-6180fe4a318f', null, 'REG-F-22', 1, 'Waste register', 'general', 'HSF-F-22', 'Hazardous waste that is stored badly or dumped can harm workers, neighbours and the environment. The register tracks what waste you create and where it goes, and signing it off every month links it to the disposal certificates in Section M.', 'draft', null, 'register', '1.1.0'),
  ('076c93ea-59db-5c65-bd0b-6bd271741aab', null, 'IND-AGRI', 1, 'Agriculture and forestry walkthrough', 'agriculture', null, 'The industry specific checks of the Agriculture and forestry overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'AGRI', 'industry', '1.1.0'),
  ('6b563a4f-a2e6-5a67-82b7-04c86ee71f97', null, 'IND-CLEAN', 1, 'Cleaning and hygiene services walkthrough', 'general', null, 'The industry specific checks of the Cleaning and hygiene services overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'CLEAN', 'industry', '1.1.0'),
  ('5cf1a945-f76c-552a-8ff2-e322ca9fbf2d', null, 'IND-CONSTR', 1, 'Construction walkthrough', 'construction', null, 'The industry specific checks of the Construction overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'CONSTR', 'industry', '1.1.0'),
  ('9cc0e939-725f-5e0e-8381-5a7af968a88e', null, 'IND-EDU', 1, 'Education walkthrough', 'general', null, 'The industry specific checks of the Education overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'EDU', 'industry', '1.1.0'),
  ('c1743060-6d66-59c9-b9ee-bc151c60a18e', null, 'IND-GOV', 1, 'Government and municipal walkthrough', 'general', null, 'The industry specific checks of the Government and municipal overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'GOV', 'industry', '1.1.0'),
  ('ce4ff14a-acc3-5fbf-93c6-3e42480d7a2f', null, 'IND-HEALTH', 1, 'Healthcare and laboratories walkthrough', 'clinics', null, 'The industry specific checks of the Healthcare and laboratories overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'HEALTH', 'industry', '1.1.0'),
  ('ef07e5b9-08b1-5c67-8ba2-0c7cc27e525a', null, 'IND-HOSP', 1, 'Hospitality and food service walkthrough', 'general', null, 'The industry specific checks of the Hospitality and food service overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'HOSP', 'industry', '1.1.0'),
  ('87688503-b0ee-5fa6-901b-19e908096c18', null, 'IND-MANU', 1, 'Manufacturing walkthrough', 'manufacturing', null, 'The industry specific checks of the Manufacturing overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'MANU', 'industry', '1.1.0'),
  ('c426346c-57e6-55b9-8606-e43db2c0045b', null, 'IND-MINING', 1, 'Mining walkthrough', 'mining', null, 'The industry specific checks of the Mining overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'MINING', 'industry', '1.1.0'),
  ('64c05783-7d6e-5a58-903f-a2686b60a865', null, 'IND-OFFICE', 1, 'Office and professional services walkthrough', 'general', null, 'The industry specific checks of the Office and professional services overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'OFFICE', 'industry', '1.1.0'),
  ('4baffabe-c9a1-5565-81e3-3a39b7584bfb', null, 'IND-PETRO', 1, 'Petrochemical and fuel retail walkthrough', 'general', null, 'The industry specific checks of the Petrochemical and fuel retail overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'PETRO', 'industry', '1.1.0'),
  ('4090e93f-b22f-561a-8948-b5c401698d7a', null, 'IND-RETAIL', 1, 'Retail and wholesale walkthrough', 'general', null, 'The industry specific checks of the Retail and wholesale overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'RETAIL', 'industry', '1.1.0'),
  ('cbc5c478-93e5-5848-b55b-e4cd2b4761c2', null, 'IND-SEC', 1, 'Security services walkthrough', 'general', null, 'The industry specific checks of the Security services overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'SEC', 'industry', '1.1.0'),
  ('e74ef962-58f0-5900-829d-680343f1cd5c', null, 'IND-TEL', 1, 'Telecommunications and tower work walkthrough', 'general', null, 'The industry specific checks of the Telecommunications and tower work overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'TEL', 'industry', '1.1.0'),
  ('57a7266e-c558-5213-9ac9-5e379fe6ee81', null, 'IND-TRANS', 1, 'Transport and logistics walkthrough', 'general', null, 'The industry specific checks of the Transport and logistics overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'TRANS', 'industry', '1.1.0'),
  ('fb918c3f-7c8b-5c91-9cc8-cb7d5f7e23db', null, 'IND-UTIL', 1, 'Utilities and energy walkthrough', 'general', null, 'The industry specific checks of the Utilities and energy overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'UTIL', 'industry', '1.1.0'),
  ('f0be030e-bd56-5548-97e0-5badb064c265', null, 'IND-WASTE', 1, 'Waste management walkthrough', 'general', null, 'The industry specific checks of the Waste management overlay in the Care Net kernel. It files with the inspection record; Section F registers are inspected with their own templates.', 'draft', 'WASTE', 'industry', '1.1.0')
insert into bi_template_item (id, template_id, ordinal, section_label, prompt, kernel_ref, source_ref) values
  ('0d4858df-37d5-5f7c-857a-76e57b8b8a6a', 'ef37f742-6dbd-5a1a-920b-1fbea8f9871f', 1, 'Records to see', 'Scaffold register listing every scaffold by number, location and erection date', 'HSF-F-01', 'guidance:HSF-F-01#what_to_submit[0]'),
  ('93547653-3849-5323-a68d-d5846523224b', 'ef37f742-6dbd-5a1a-920b-1fbea8f9871f', 2, 'Records to see', 'Signed inspection records by your appointed scaffold inspector', 'HSF-F-01', 'guidance:HSF-F-01#what_to_submit[1]'),
  ('7bb6907d-a0fb-5197-b702-3a325f3286fa', 'ef37f742-6dbd-5a1a-920b-1fbea8f9871f', 3, 'Records to see', 'Handover or tag record showing each scaffold was declared safe before use', 'HSF-F-01', 'guidance:HSF-F-01#what_to_submit[2]'),
  ('13731bef-54a0-5dcf-9f03-d9a573ded290', 'ef37f742-6dbd-5a1a-920b-1fbea8f9871f', 4, 'Gaps to look for (Pass means not found)', 'Inspection pages signed by someone who is not the appointed scaffold inspector', 'HSF-F-01', 'guidance:HSF-F-01#common_gaps[0]'),
  ('36170112-3cc5-5700-b8ab-161f05bb2b0e', 'ef37f742-6dbd-5a1a-920b-1fbea8f9871f', 5, 'Gaps to look for (Pass means not found)', 'Scaffolds hired in by a subcontractor missing from your register', 'HSF-F-01', 'guidance:HSF-F-01#common_gaps[1]'),
  ('35dfe5ca-4277-5c73-8c83-9b6db18c35d9', 'ef37f742-6dbd-5a1a-920b-1fbea8f9871f', 6, 'Gaps to look for (Pass means not found)', 'No inspection recorded after strong wind or heavy rain', 'HSF-F-01', 'guidance:HSF-F-01#common_gaps[2]'),
  ('5efb2185-ae33-515d-811b-0e990d56d4be', '1a88bcc5-71ff-5df5-b677-7349ba8aa449', 1, 'Records to see', 'Ladder register with a number, type and location for every ladder', 'HSF-F-02', 'guidance:HSF-F-02#what_to_submit[0]'),
  ('293f92b3-0e5b-5acd-8faa-906a71b5f394', '1a88bcc5-71ff-5df5-b677-7349ba8aa449', 2, 'Records to see', 'Inspection checklist pages signed by your ladder inspector', 'HSF-F-02', 'guidance:HSF-F-02#what_to_submit[1]'),
  ('e4341d6d-b10b-59bf-ad66-cd119a34b590', '1a88bcc5-71ff-5df5-b677-7349ba8aa449', 3, 'Records to see', 'A note of damaged ladders removed from use and how they were destroyed', 'HSF-F-02', 'guidance:HSF-F-02#what_to_submit[2]'),
  ('df640dd3-62af-5c7b-83b9-96413511f41b', '1a88bcc5-71ff-5df5-b677-7349ba8aa449', 4, 'Gaps to look for (Pass means not found)', 'Ladders in the storeroom or vehicles never added to the register', 'HSF-F-02', 'guidance:HSF-F-02#common_gaps[0]'),
  ('b6aa7a37-c2f7-573d-b6ed-1a9f2c030cb9', '1a88bcc5-71ff-5df5-b677-7349ba8aa449', 5, 'Gaps to look for (Pass means not found)', 'Damaged ladders marked on the register but still in use', 'HSF-F-02', 'guidance:HSF-F-02#common_gaps[1]'),
  ('8eb8fd09-f7b6-5b3c-ac50-fc7fd5dc222e', '1a88bcc5-71ff-5df5-b677-7349ba8aa449', 6, 'Gaps to look for (Pass means not found)', 'Homemade or painted over wooden ladders that hide defects', 'HSF-F-02', 'guidance:HSF-F-02#common_gaps[2]'),
  ('d5f7eb35-6848-5467-b6bc-0ca620464cbd', 'd3d23e55-cb3b-5b66-b119-fd580aa12517', 1, 'Records to see', 'Register of every lifting machine and item of lifting tackle, with a unique number and safe working load', 'HSF-F-03', 'guidance:HSF-F-03#what_to_submit[0]'),
  ('8e220c57-157b-5fa8-9696-84f57dc79a76', 'd3d23e55-cb3b-5b66-b119-fd580aa12517', 2, 'Records to see', 'Load test certificates for each machine', 'HSF-F-03', 'guidance:HSF-F-03#what_to_submit[1]'),
  ('b76bc7ab-490a-5a45-85bb-f6601eff8f27', 'd3d23e55-cb3b-5b66-b119-fd580aa12517', 3, 'Records to see', 'Signed inspection records by your lifting machine and lifting tackle inspector', 'HSF-F-03', 'guidance:HSF-F-03#what_to_submit[2]'),
  ('205ab6f1-817c-50cc-99ff-c9dd45916266', 'd3d23e55-cb3b-5b66-b119-fd580aa12517', 4, 'Gaps to look for (Pass means not found)', 'Slings and shackles not individually numbered, so nobody can prove which were inspected', 'HSF-F-03', 'guidance:HSF-F-03#common_gaps[0]'),
  ('eed994fa-55f6-5d43-8b70-6819496c5276', 'd3d23e55-cb3b-5b66-b119-fd580aa12517', 5, 'Gaps to look for (Pass means not found)', 'Load test certificates expired or missing for hired equipment', 'HSF-F-03', 'guidance:HSF-F-03#common_gaps[1]'),
  ('cb613e65-8709-5389-a078-75d334a5b57a', 'd3d23e55-cb3b-5b66-b119-fd580aa12517', 6, 'Gaps to look for (Pass means not found)', 'Damaged tackle left in the rack instead of being quarantined', 'HSF-F-03', 'guidance:HSF-F-03#common_gaps[2]'),
  ('bc194b84-ab5b-59d4-9248-5cbbcc84c5a8', 'd9f3241d-af31-54c4-ad27-900a2d27eaab', 1, 'Records to see', 'Register of portable electrical tools and extension leads with an asset number for each', 'HSF-F-04', 'guidance:HSF-F-04#what_to_submit[0]'),
  ('b2e681cc-a0e0-5f35-9251-e0a22e048841', 'd9f3241d-af31-54c4-ad27-900a2d27eaab', 2, 'Records to see', 'Inspection and test records signed by the appointed electrical installation supervisor', 'HSF-F-04', 'guidance:HSF-F-04#what_to_submit[1]'),
  ('2fbbc7dc-a7d4-51ab-bce4-52edfbd7ff59', 'd9f3241d-af31-54c4-ad27-900a2d27eaab', 3, 'Records to see', 'Record of faulty tools withdrawn and repaired or scrapped', 'HSF-F-04', 'guidance:HSF-F-04#what_to_submit[2]'),
  ('40bdc8f3-f9e8-5d75-862b-431155acc9ef', 'd9f3241d-af31-54c4-ad27-900a2d27eaab', 4, 'Gaps to look for (Pass means not found)', 'Workers'' own tools brought from home never inspected', 'HSF-F-04', 'guidance:HSF-F-04#common_gaps[0]'),
  ('c5a7a92e-0134-5660-8d8d-b388d21834eb', 'd9f3241d-af31-54c4-ad27-900a2d27eaab', 5, 'Gaps to look for (Pass means not found)', 'Extension leads and multi plugs left off the register', 'HSF-F-04', 'guidance:HSF-F-04#common_gaps[1]'),
  ('aa1a8f13-2487-51d5-bc0a-c50b9ae28f43', 'd9f3241d-af31-54c4-ad27-900a2d27eaab', 6, 'Gaps to look for (Pass means not found)', 'Tags on the tools but no matching register entry', 'HSF-F-04', 'guidance:HSF-F-04#common_gaps[2]'),
  ('bd63b005-72e8-59d3-893b-3d2213249f15', 'cd03242f-8a9f-5b06-819e-c17797c7712d', 1, 'Records to see', 'Electrical certificate of compliance for each site or installation', 'HSF-F-05', 'guidance:HSF-F-05#what_to_submit[0]'),
  ('0a77b6c8-7f92-53e2-a525-9c53d8df2673', 'cd03242f-8a9f-5b06-819e-c17797c7712d', 2, 'Records to see', 'Installation inspection register signed by the electrical installation supervisor', 'HSF-F-05', 'guidance:HSF-F-05#what_to_submit[1]'),
  ('4a38c92b-2c34-5940-8dd5-17912f3bd696', 'cd03242f-8a9f-5b06-819e-c17797c7712d', 3, 'Records to see', 'A new certificate or record for every alteration or addition to the installation', 'HSF-F-05', 'guidance:HSF-F-05#what_to_submit[2]'),
  ('b5e3ff15-f056-5bd8-879a-ca4e9f839bff', 'cd03242f-8a9f-5b06-819e-c17797c7712d', 4, 'Gaps to look for (Pass means not found)', 'Relying on the landlord''s certificate without a copy on file', 'HSF-F-05', 'guidance:HSF-F-05#common_gaps[0]'),
  ('2165d211-b768-5ebb-b72f-e6015cad7896', 'cd03242f-8a9f-5b06-819e-c17797c7712d', 5, 'Gaps to look for (Pass means not found)', 'No new certificate after a circuit or distribution board was added', 'HSF-F-05', 'guidance:HSF-F-05#common_gaps[1]'),
